function syncSceneActivity(){scene?.setActive(nativeActive&&!document.hidden&&tab==='explore');}
/** Timetables use the device clock; no network or background minute polling. */
function scheduleBusRefresh(refreshNow=false){
 clearTimeout(busRefreshTimer);busRefreshTimer=undefined;
 if(tab!=='buses'||document.hidden||!nativeActive)return;
 if(refreshNow)renderBuses();
 if(!knowledge().busRoutes.length)return;
 busRefreshTimer=window.setTimeout(()=>scheduleBusRefresh(true),60000-Date.now()%60000+1);
}
const L=(en:string,ko:string,zh?:string)=>t(en,ko,lang,zh);
const localized=(value:Localized|undefined)=>value?localize(value,lang):'';
const mapUsageNote=()=>L('Map positions are approximate. Entrances and step-free routes are not verified. Follow campus signs.','지도 위치는 대략적입니다. 출입구와 계단 없는 경로는 확인되지 않았습니다. 교내 표지판을 확인하세요.','地图位置仅供参考；入口及无台阶路线尚未核实，请以校园标识为准。');
const tabs=()=>[{id:'explore',label:L('Explore','탐색')},{id:'food',label:L('Food','음식')},{id:'buses',label:L('Buses','버스')},{id:'chat',label:L('Ask','질문')},{id:'events',label:L('Events','행사')}];
const send=(m:NativeMessage)=>{if(!window.ReactNativeWebView)return false;window.ReactNativeWebView.postMessage(JSON.stringify(m));return true;};
function persist(){const p={language:lang,campusId,favorites:[...favorites]};if(!send({type:'save',...p}))try{localStorage.setItem('mce-preferences-v1',JSON.stringify(p));}catch{toast(L('Saved for this session.','이번 세션에 저장되었습니다.'));}}
function load(){try{const p=JSON.parse(localStorage.getItem('mce-preferences-v1')||'{}');if(p.language==='en'||p.language==='ko'||p.language==='zh')lang=p.language;if(isCampusId(p.campusId))campusId=p.campusId;data=datasets[campusId];messages=campusChats[campusId];routeId=knowledge().busRoutes[0]?.id||'';if(Array.isArray(p.favorites))favorites=new Set(p.favorites.filter((v:unknown)=>typeof v==='string'));}catch{}}
function openExternal(url:string){if(safeExternalUrl(url)&&!send({type:'external',url}))window.open(url,'_blank','noopener,noreferrer');}
function naverButton(id:string){const links=naverLinksForPlace(campusId,id);if(!links)return '';return `<button class="text-button" data-action="naver-map">${links.kind==='marker'?L('Open in Naver Maps','네이버 지도에서 열기','在Naver地图中打开'):L('Search Naver Maps','네이버 지도에서 검색','在Naver地图中搜索')}${icon('external')}</button>`;}
function openNaver(){
 if(!selected)return;const links=naverLinksForPlace(campusId,selected);if(!links)return;
 if(typeof window.MCENaver?.open==='function'){try{window.MCENaver.open(links.nativeRequestUrl);}catch{openExternal(links.webUrl);}}else openExternal(links.webUrl);
}
function sourceButtons(ids:string[]){return ids.map(id=>{const s=knowledge().sources.find(v=>v.id===id);const profile=campusId==='yongin'?getCommunitySource(id):undefined;return s?`<button class="source-link" data-source="${esc(s.id)}">${icon('book')}${esc(localized(s.title))}</button>`:profile?`<button class="source-link" data-source="${profile.id}">${icon('book')}${esc(profile.handle)} · ${esc(localized(profile.title))}</button>`:'';}).join('');}
