 const canvas=$<HTMLCanvasElement>('campus-canvas');canvas.addEventListener('scenefailed',()=>{sceneFailed=true;$('map-failure').hidden=false;stopLocation('paused');renderLocation();});canvas.addEventListener('keydown',e=>{if(['+','=','-','r','Home'].includes(e.key)){e.preventDefault();if(e.key==='+'||e.key==='=')scene?.zoomBy(1.2);if(e.key==='-')scene?.zoomBy(.8);if(e.key==='r')scene?.rotate();if(e.key==='Home')scene?.reset();}});
