function renderPanel(){if(tab==='explore'){
 heading(L('EXPLORE CAMPUS','캠퍼스 둘러보기','探索校园'),L('Where are you headed?','어디로 가시나요?'),L('Search by building name or code.','건물 이름이나 코드로 검색하세요.','按建筑名称或代码搜索。'));
 $('panel-body').innerHTML=`<div class="search-wrap">${icon('search')}<input id="search" type="search" placeholder="${L('Building name or code','건물 이름 또는 코드')}" aria-label="${L('Search buildings','건물 검색')}" value="${esc(query)}"><button class="icon-button ${onlySaved?'saved':''}" data-action="saved-filter" aria-label="${L('Show saved places','즐겨찾기 표시')}" aria-pressed="${onlySaved}">${icon('heart')}</button></div><div class="filter-row">${[['all',L('All','전체')],['academic',L('Academic','교육')],['library',L('Library','도서관')],['residence',L('Living','생활')],['outdoors',L('Outdoors','야외')]].map(([id,title])=>`<button class="chip ${category===id?'active':''}" data-category="${id}" aria-pressed="${category===id}">${title}</button>`).join('')}</div><div id="results"></div>`;$('search').addEventListener('input',e=>{query=(e.target as HTMLInputElement).value;renderPlaces();});renderPlaces();
 }else if(tab==='food'){
 heading(L('FOOD & SHOPS','식당과 매장','餐饮与商店'),L('Where to eat and shop','식당과 매장 찾기','查找餐饮与商店'),L('Check current opening hours and prices before visiting.','방문 전 최신 운영 시간과 가격을 확인하세요.','前往前请确认最新营业时间和价格。'));
 $('panel-body').innerHTML=`${communitySection('menu')}<div class="filter-row">${[['all',L('Everything','전체')],['cafe',L('Coffee','커피')],['cafeteria',L('Meals','식사')],['restaurant',L('Quick bites','간식')],['convenience',L('Shops','편의점')]].map(([id,title])=>`<button class="chip ${foodKind===id?'active':''}" data-food-kind="${id}" aria-pressed="${foodKind===id}">${title}</button>`).join('')}</div><div class="food-grid">${knowledge().food.filter(v=>foodKind==='all'||v.kind===foodKind).map(v=>`<article class="food-card"><div class="food-card-top"><span class="food-symbol ${v.kind}">${icon(v.kind==='cafe'?'coffee':'food')}</span><span class="small-tag">${esc(v.placeCode||'')}</span></div><h3>${esc(localized(v.name))}</h3><p class="location-line">${esc(localized(v.location))}</p><div class="card-actions">${placeActions(v.placeCode?[v.placeCode]:[])}<button class="text-button" data-source="${v.sourceIds[0]}">${L('Source','출처')}${icon('external')}</button></div></article>`).join('')}</div>${foodReadingNote()}`;
 }else if(tab==='buses')renderBuses();else if(tab==='chat')renderChat();else renderEvents();}
function foodReadingNote(){return campusId==='yongin'?`<div class="reading-note">${icon('book')}<div><b>${L('From the student guide','학생 안내에서')}</b><p>${L('Find nearby restaurants and cafés in the student guide.','학생 안내서에서 주변 식당과 카페를 찾아보세요.','可在学生指南中查找附近的餐厅和咖啡馆。')}</p><button class="source-link" data-source="notion-guide">${L('Read the supplied guide','제공된 안내 보기')}${icon('external')}</button></div></div>`:'';}
function renderPlaces(){const q=normalize(query);const referenceIds=new Set(CAMPUSES[campusId].referencePlaces().map(p=>p.id));const unverifiedRefs=data.places.filter(p=>referenceIds.has(p.id)&&p.evidence.status==='unverified'&&(category==='all'||p.category===category)&&(!onlySaved||favorites.has(p.id))&&(!q||[p.name.en,p.name.ko,localized(p.name),p.code||'',...p.aliases].some(s=>normalize(s).includes(q))));const places=[...searchPlaces(data,query,category,onlySaved?favorites:undefined),...unverifiedRefs].filter(p=>p.id!=='mju-yongin-campus'&&p.id!=='mju-seoul-campus');$('results').innerHTML=`<div class="results-meta"><span>${onlySaved?L('SAVED PLACES','즐겨찾기'):query?L('SEARCH RESULTS','검색 결과'):L('CAMPUS DIRECTORY','캠퍼스 목록')}</span><b>${places.length}</b></div>${places.map(p=>`<button class="place-card ${selected===p.id?'selected':''}" data-place="${esc(p.id)}"><span class="building-code">${esc(p.code||'•')}</span><span><strong>${esc(localized(p.name))}</strong><small>${esc(p.name[lang==='ko'?'en':'ko'])}</small></span>${favorites.has(p.id)?icon('heart'):icon('pin')}</button>`).join('')||`<div class="empty-state"><h3>${L('No matching places','검색 결과가 없습니다')}</h3><p>${L('Search in English, Korean or Chinese, or enter a building code.','영어·한국어·중국어 이름이나 건물 코드를 입력하세요.','可用英语、韩语、中文或建筑代码搜索。')}</p></div>`}`;}
function changeCampus(next:CampusId){if(next===campusId){setTab('explore');return;}chatMapReturn=null;tab='explore';campusSelections[campusId]=selected;campusChats[campusId]=messages;campusId=next;data=datasets[next];selected=campusSelections[next];messages=campusChats[next];for(const m of messages)m.result=answerQuestion(m.question,lang,campusId);query='';category='all';foodKind='all';onlySaved=false;routeId=knowledge().busRoutes[0]?.id||'';contentState='bundled';persist();mount();}
function changeLanguage(next:Language){if(next===lang)return;lang=next;for(const m of messages)m.result=answerQuestion(m.question,lang,campusId);persist();mount();}
function selectPlace(id:string){if(!data.places.some(p=>p.id===id))return;chatMapReturn=null;selected=id;if(tab!=='explore')setTab('explore');scene?.select(id);renderSheet();if($('results'))renderPlaces();$('workspace').scrollTop=0;if(window.matchMedia('(max-width:760px)').matches)requestAnimationFrame(()=>{if(selected!==id||tab!=='explore')return;const sheet=$('place-sheet'),target=sheet.offsetHeight>$('workspace').clientHeight?sheet.querySelector<HTMLElement>('.sheet-actions')!:sheet;target.scrollIntoView({block:'nearest',behavior:'auto'});});}
function renderSheet(){const p=data.places.find(p=>p.id===selected);$('place-sheet').hidden=!p;if(!p)return;$('place-sheet').innerHTML=`<div class="sheet-heading"><span class="small-tag">${esc(p.code||L('Campus','캠퍼스'))}</span><button class="icon-button ${favorites.has(p.id)?'saved':''}" data-action="favorite" aria-label="${L('Save building','건물 저장')}" aria-pressed="${favorites.has(p.id)}">${icon('heart')}</button><button class="icon-button" data-action="close-place" aria-label="${L('Close building details','건물 상세 닫기')}">${icon('close')}</button></div><h2>${esc(localized(p.name))}</h2><p class="alternate-name">${esc(p.name[lang==='ko'?'en':'ko'])}</p><div class="sheet-actions"><button class="primary-button" data-action="place-detail">${L('Building information','건물 정보')}${icon('info')}</button><button class="text-button" data-ask="${esc(p.code?`Where is ${p.code}?`:p.name.en)}">${L('Ask about it','질문하기')}${icon('chat')}</button>${naverButton(p.id)}${chatMapReturn?`<button class="text-button" data-action="return-chat">${L('Back to answer','답변으로 돌아가기','返回回答')}${icon('chat')}</button>`:''}</div>`;}
function renderBuses(){heading(L('ON YOUR WAY','가는 길에'),L('Catch the campus bus.','캠퍼스 버스를 타세요.'),L('Published departure times · Seoul (KST)','공개 출발시간 · 한국 시간(KST)'));if(!knowledge().busRoutes.length){$('panel-body').innerHTML=`<article class="empty-state transport-empty">${icon('buses')}<h3>${L('No timetable saved for this campus.','이 캠퍼스의 저장된 시간표가 없습니다.','暂无此校区的已保存时刻表。')}</h3><p>${localized(knowledge().transportSummary)}</p>${sourceButtons(knowledge().transportSourceIds||[])}</article>`;return;}const r=knowledge().busRoutes.find(v=>v.id===routeId)!,s=scheduledDepartures(routeId,new Date(),campusId),next=new Set(s.times.slice(0,3));
 $('panel-body').innerHTML=`<label class="field-label" for="bus-route">${L('Choose a published timetable','공개 시간표 선택')}</label><select id="bus-route">${knowledge().busRoutes.map(v=>`<option value="${v.id}" ${v.id===routeId?'selected':''}>${esc(localized(v.name))} · ${esc(localized(v.service))}</option>`).join('')}</select><article class="bus-card"><span class="bus-glyph">${icon('buses')}</span><h3>${esc(localized(r.name))}</h3><div class="route-stops"><div><small>${L('DEPARTURE','출발')}</small><strong>${esc(localized(r.origin))}</strong></div><span class="route-connector"></span><div><small>${L('DESTINATION','도착')}</small><strong>${esc(localized(r.destination))}</strong></div></div><p>${esc(localized(r.service))}</p></article><div class="notice">${icon('info')}<p>${L('Today’s operation is unconfirmed. These are scheduled departures from the origin, not live arrivals at your stop.','오늘 운행 여부는 미확인입니다. 정류장 실시간 도착정보가 아닌 출발지 기준 예정시간입니다.')}</p></div><p class="schedule-eligibility">${esc(r.validFrom)} – ${esc(r.validThrough)}<br>${esc(localized(s.eligibilityNote))}</p><div class="time-heading"><h3>${L('Published timetable','공개 시간표')}</h3><span>${esc(s.localTime)} KST</span></div><p class="muted">${L('Highlighted: the next listed times after the current Seoul time, if this timetable operates.','강조 표시: 이 시간표가 운행되는 경우, 현재 한국 시간 이후의 다음 예정시간.')}</p><div class="time-grid">${r.times.map(t=>`<span class="time-cell ${next.has(t)?'next':''}">${t}</span>`).join('')}</div>${s.availability==='conditional'&&!s.times.length?`<p class="muted">${L('No later departures listed at the current Seoul time.','현재 한국 시간 이후의 출발시간이 없습니다.')}</p>`:''}<div class="reading-note"><div><b>${L('Read before travelling','이용 전 확인')}</b><p>${esc(localized(r.note))}</p>${sourceButtons(r.sourceIds)}<small>${L('Scheduled times, not live arrivals.','예정시간이며 실시간 도착정보가 아닙니다.','所列为计划时刻，并非实时到站信息。')}</small></div></div>`;$('bus-route').addEventListener('change',e=>{routeId=(e.target as HTMLSelectElement).value;renderBuses();});}
function renderChat(){heading(L('CAMPUS QUESTIONS','캠퍼스 질문','校园问答'),L('Ask about campus','캠퍼스에 대해 물어보세요','询问校园信息'),campusId==='yongin'?L('Ask about buildings, meals, buses or student services.','건물, 식사, 버스, 학생 서비스에 대해 물어보세요.','可询问建筑、餐饮、校车或学生服务。'):L('Ask about buildings, meals, transport or student services.','건물, 식사, 교통, 학생 서비스에 대해 물어보세요.','可询问建筑、餐饮、交通或学生服务。'));
 $('panel-body').innerHTML=`<div class="chat-intro"><span>${icon('chat')}</span><div><b>${L('Ask Campus','캠퍼스에 질문하기')}</b><p>${L('Works offline with saved campus information.','저장된 캠퍼스 정보로 오프라인에서도 답합니다.','使用已保存的校园信息，可离线回答。')}</p></div></div><div class="suggestions">${[[L('Where can I get coffee?','커피는 어디서 사나요?'),'coffee'],[campusId==='yongin'?L('Where is classroom Y9228?','Y9228 강의실은 어디인가요?','Y9228教室在哪里？'):L('Where is the library?','도서관은 어디인가요?','图书馆在哪里？'),'book'],[L('How do I use the library?','도서관 이용은 어떻게 하나요?'),'explore'],[L('What are the bus times?','버스 시간표를 알려주세요'),'buses']].map(([q,i])=>`<button data-ask="${esc(q!)}">${icon(i!)}${esc(q!)}</button>`).join('')}</div><div id="chat-messages" class="chat-messages" role="log" aria-live="polite"></div><form id="chat-form" class="chat-form"><label class="sr-only" for="chat-input">${L('Ask a campus question','캠퍼스 질문')}</label><textarea id="chat-input" rows="2" maxlength="1000" placeholder="${L('Ask about a building, a meal, a bus…','건물, 식사, 버스에 대해 물어보세요…')}" required></textarea><button class="primary-button" type="submit" aria-label="${L('Send question','질문 보내기')}">${icon('send')}</button></form><div class="chat-footer"><span>${L('Chat stays in this session. No personal timetable access.','대화는 이번 세션에만 유지됩니다. 개인 시간표에 접근하지 않습니다.')}</span><button class="text-button" data-action="clear-chat">${L('Clear chat','대화 지우기')}</button></div>`;$('chat-form').addEventListener('submit',e=>{e.preventDefault();const input=$<HTMLTextAreaElement>('chat-input');ask(input.value);input.value='';input.focus();});renderMessages();}
function ask(question:string){const q=question.trim().slice(0,1000);if(!q)return;if(tab!=='chat')setTab('chat');messages.push({question:q,result:answerQuestion(q,lang,campusId)});if(messages.length>30)messages.shift();renderMessages();}
function renderMessages(){const log=$('chat-messages');if(!log)return;log.innerHTML=messages.map((m,messageIndex)=>`<div class="message user-message"><span>${esc(m.question)}</span></div><article class="message answer-message"><span class="answer-label">${icon('chat')} ${L('Ask Campus','캠퍼스에 질문하기','校园问答')}</span><p>${esc(m.result.answer)}</p>${m.result.citations.length?`<div class="citations">${sourceButtons(m.result.citations)}</div>`:''}${m.result.placeCodes.length||m.result.placeIds?.length?`<div class="answer-places">${placeActions(m.result.placeCodes,messageIndex,m.result.placeIds)}</div>`:''}${!m.result.placeCodes.length&&!m.result.placeIds?.length&&/bus|shuttle|버스|셔틀|巴士|公交|班车|校车/i.test(m.question)?`<button class="chip" data-tab="buses">${icon('buses')}${L('Open timetables','시간표 보기')}</button>`:''}</article>`).join('');log.lastElementChild?.scrollIntoView({block:'nearest',behavior:'auto'});}
function renderEvents(){
 heading(L('AROUND CAMPUS','캠퍼스 소식'),L('What’s happening.','지금 캠퍼스에서는.'),L('Saved campus events and notices · Seoul time (KST)','저장된 캠퍼스 행사와 소식 · 한국 시간','已保存的校园活动与通知 · 韩国时间'));
 const events=upcomingEvents(data,new Date());
 const savedEvents=events.length?events.map(e=>`<article class="food-card"><span class="small-tag">${new Intl.DateTimeFormat(lang,{timeZone:'Asia/Seoul',dateStyle:'medium'}).format(new Date(e.startsAt))}</span><h3>${esc(localized(e.title))}</h3><p>${esc(localized(e.description))}</p><button class="chip" data-place="${esc(e.placeId)}">${L('Show venue','장소 보기')}</button>${e.evidence.sourceUrl&&safeExternalUrl(e.evidence.sourceUrl)?`<button class="source-link" data-url="${esc(e.evidence.sourceUrl)}">${L('Event source','행사 출처','活动来源')}${icon('external')}</button>`:''}</article>`).join(''):`<div class="empty-state event-empty">${icon('events')}<h3>${L('No upcoming events saved.','저장된 예정 행사가 없습니다.','暂无已保存的即将举行的活动。')}</h3><p>${L('Check university notices for upcoming events.','예정된 행사는 대학 공지를 확인하세요.','即将举行的活动请查看大学公告。')}</p><button class="primary-button" data-url="https://www.mju.ac.kr/mjukr/index.do">${L('University website','대학 홈페이지')}${icon('external')}</button></div>`;
 $('panel-body').innerHTML=communitySection('announcement')+savedEvents;
}
function dialog(html:string){
 const active=document.activeElement as HTMLElement;if(active&&!$('dialog').contains(active))lastFocus=active;$('dialog-content').innerHTML=html;
 const modal=$<HTMLDialogElement>('dialog'),title=$('dialog-content').querySelector('h2');
 if(title){title.id='dialog-title';modal.setAttribute('aria-labelledby',title.id);modal.removeAttribute('aria-label');}
 else{modal.removeAttribute('aria-labelledby');modal.setAttribute('aria-label',L('Campus information','캠퍼스 정보','校区信息'));}
 modal.showModal();
}
function closeDialog(){$<HTMLDialogElement>('dialog').close();}
// One synchronous contract for Android Back. Only the Explore root may exit.
function handleBack():boolean{
 if($<HTMLDialogElement>('dialog').open){closeDialog();return true;}
 if(tab==='explore'&&chatMapReturn){returnToChat();return true;}
 if(tab!=='explore'){setTab('explore');return true;}
 if(selected){selected=null;scene?.select(null);renderSheet();renderPlaces();return true;}
 if(query||category!=='all'||onlySaved){query='';category='all';onlySaved=false;renderPanel();return true;}
 return false;
}
function sourceDialog(id:string){const profile=campusId==='yongin'?getCommunitySource(id):undefined;if(profile){communitySourceDialog(profile);return;}const s=knowledge().sources.find(v=>v.id===id);if(!s)return;dialog(`<span class="small-tag">${s.kind==='official'?L('University source','대학 출처'):L('Supplied reference','제공된 참고자료')}</span><h2>${esc(localized(s.title))}</h2><p>${esc(localized(s.note))}</p><p class="muted">${L('Checked / imported','확인 / 가져온 날짜')}: ${s.checkedAt}${s.publishedAt?` · ${L('Published','게시일')}: ${s.publishedAt}`:''}</p>${s.url?`<button class="primary-button" data-url="${esc(s.url)}">${L('Open original source','원문 열기')}${icon('external')}</button>`:''}`);}

function visualReference(id:string){const ref=VISUAL_REFERENCES[id];if(!ref)return '';const sources=ref.sources.filter(s=>s.reviewed&&s.kind!=='directory');if(!sources.length&&!ref.imageUrl)return '';return `<section class="visual-reference"><h3>${L('Photos and campus views','사진과 캠퍼스 전경','照片与校园全景')}</h3><div class="reference-actions">${sources.slice(0,3).map(s=>`<button class="source-link" data-url="${esc(s.url)}">${icon(s.kind==='official-video'?'external':'book')}${esc(s.kind==='official-video'?L('University tour','대학 투어 영상'):s.kind==='official-overview'?L('Campus overview','캠퍼스 조감도'):s.kind==='architect-photo'?L('Architect’s photographs','설계사 사진'):L('Source photographs','출처 사진'))}${s.frameTime?` · ${esc(s.frameTime)}`:''}</button>`).join('')}${ref.imageUrl?`<button class="source-link" data-url="${esc(ref.imageUrl)}">${icon('external')}${L('Open image reference','사진 참고자료 열기')}</button>`:''}</div><p class="reference-date">${L('Reviewed','검토일')} ${ref.checkedAt}</p></section>`;}
function showVisualReference(id:string){const ref=VISUAL_REFERENCES[id];if(!ref)return;const p=data.places.find(p=>p.id===id);dialog(`<span class="small-tag">${esc(ref.code||'')}</span><h2>${esc(localized(p?.name)||ref.nameEn)}</h2>${visualReference(id)}`);}
function showSources(){dialog(`<h2>${L('Sources','정보 출처','资料来源')}</h2><p>${L('Campus information comes from Myongji University pages and the supplied student guide. If they differ, follow the university. English and Chinese building names are translations.','캠퍼스 정보는 명지대학교 페이지와 제공된 학생 안내서를 바탕으로 합니다. 내용이 다르면 대학 안내를 따르세요. 영어·중국어 건물 이름은 번역입니다.','校园信息来自明知大学网页及提供的学生指南。如有不同，请以大学公布的信息为准。英文和中文建筑名称为翻译。')}</p><div class="source-list">${knowledge().sources.map(s=>`<button data-source="${s.id}"><b>${esc(localized(s.title))}</b><small>${s.checkedAt} · ${s.kind==='official'?L('Official','공식'):L('Reference','참고')}</small>${icon('external')}</button>`).join('')}</div>${communitySources(campusId).length?`<h3>${L('Cafeteria and community sources','식당과 커뮤니티 출처','食堂与社区来源')}</h3><p>${esc(communityExternalNote())}</p><div class="source-list">${communitySources(campusId).map(source=>`<button data-source="${source.id}"><b>${esc(source.handle)} · ${esc(localized(source.title))}</b><small>${esc(communityGuideLabel(source))}</small>${icon('book')}</button>`).join('')}</div>`:''}<button class="source-link" data-action="map-evidence">${L('Map sources','지도 출처','地图来源')}</button>`);}
function about(){dialog(`<h2>${L('About Campus Explorer','Campus Explorer 소개','关于Campus Explorer')}</h2><div class="about-signature"><img src="__MYONGJI_SIGNATURE_DATA_URI__" width="237" height="60" alt="Myongji University · 명지대학교"></div><p>${L('Myongji Campus Explorer is an independent student project. It is not an official university application or an endorsed navigation service.','Myongji Campus Explorer는 독립 학생 프로젝트이며 대학 공식 앱 또는 공인 길 안내 서비스가 아닙니다.')}</p><h3>${L('Your privacy','개인정보')}</h3><p>${L('Campus selection, favorites and language preferences stay on your device. Questions are answered locally from saved sources; chats last only for this session. This build has no analytics, ads or account. It does not read your student timetable or store location history.','캠퍼스 선택, 즐겨찾기와 언어 설정은 기기에 저장됩니다. 질문은 저장된 출처를 바탕으로 기기에서 답하며 대화는 이번 세션에만 유지됩니다. 분석, 광고, 계정 기능은 없으며 개인 시간표나 위치 기록을 수집하지 않습니다.')}</p><p>${L('Source links open external services with their own privacy policies. They may require internet or sign-in. Optional information updates use the configured content service; Instagram posts are not imported automatically.','출처 링크는 자체 개인정보 정책이 적용되는 외부 서비스를 엽니다. 인터넷이나 로그인이 필요할 수 있습니다. 선택한 정보 업데이트는 연결된 정보 서비스를 사용하며 Instagram 게시물을 자동으로 가져오지 않습니다.','来源链接会打开适用其自身隐私政策的外部服务，可能需要联网或登录。可选的信息更新使用已连接的内容服务；Instagram帖子不会自动导入。')}</p><p>${L('My location requests foreground permission only when tapped. You may allow approximate location. The point and accuracy circle use device coordinates in memory; they stop when you leave the map and are not saved or sent by this app.','내 위치를 누를 때만 포그라운드 위치 권한을 요청합니다. 대략적인 위치를 허용해도 됩니다. 위치와 정확도 원은 기기 좌표를 메모리에서만 사용하며 지도를 벗어나면 중지됩니다. 앱은 좌표를 저장하거나 전송하지 않습니다.','仅点击“我的位置”时才请求前台位置权限，也可允许大致位置。位置点和精度圆仅在内存中使用设备坐标，离开地图后停止；本应用不保存或发送坐标。')}</p><button class="chip" data-action="clear-saved">${L('Clear saved places','즐겨찾기 지우기')}</button><button class="chip" data-action="sources">${L('View sources','출처 보기')}</button>${publisherPrivacy?`<button class="chip" data-url="${esc(publisherPrivacy)}">${L('Privacy policy','개인정보 처리방침')}</button>`:''}${publisherSupport?`<button class="chip" data-url="${esc(publisherSupport)}">${L('Contact support','지원 문의')}</button>`:''}<p class="muted">v0.6.1 · ${L('Independent mobile project','독립 모바일 프로젝트')} · ${L('Two campuses · English, Korean & Chinese','두 캠퍼스 · 영어·한국어·중국어','双校区 · 英语、韩语、中文')}</p>`);}
function seoulMapEvidence(){dialog(`<h2>${L('Seoul · map sources','서울 · 지도 출처','首尔 · 地图来源')}</h2><p>${L('Building names and map locations come from the university campus directory.','건물 이름과 지도 위치는 대학 캠퍼스 안내를 바탕으로 합니다.','建筑名称和地图位置依据大学校园目录。')}</p><p>${mapUsageNote()}</p><button class="primary-button" data-url="${CAMPUSES.seoul.directoryUrl}">${L('Official campus map','공식 캠퍼스 지도','官方校区地图')}${icon('external')}</button><button class="source-link" data-url="https://www.mju.ac.kr/bbs/record/359/168757/download.do">${L('University campus overview','대학 캠퍼스 안내도','大学校区全景图')}${icon('external')}</button><button class="source-link" data-url="https://gsca.mju.ac.kr/CrossEditor/binary/images/000355/20251128163849970_107N73HV.png">${L('Official campus photograph','대학 캠퍼스 사진','官方校区照片')}${icon('external')}</button>`);}
function mapEvidence(){if(campusId==='seoul'){seoulMapEvidence();return;}const refs=Object.values(VISUAL_REFERENCES).filter(ref=>ref.imageUrl||ref.sources.some(s=>s.reviewed&&s.kind!=='directory'));dialog(`<h2>${L('Yongin · map sources','용인 · 지도 출처','龙仁 · 地图来源')}</h2><p>${L('The map uses the university campus directory and 2021 site plan. Photo and video sources are listed below.','지도는 대학 캠퍼스 안내와 2021년 배치도를 바탕으로 합니다. 사진과 영상 출처는 아래에서 확인하세요.','地图依据大学校园目录和2021年总平面图；照片和视频来源见下方。')}</p><p>${mapUsageNote()}</p><button class="primary-button" data-url="https://www.mju.ac.kr/campusMap/mjukr/view.do?findType=B">${L('Official campus map','공식 캠퍼스 지도')}${icon('external')}</button><button class="source-link" data-url="${PLAN_CALIBRATION.sourceUrl}">${L('2021 university site plan','2021년 대학 배치도','2021年大学总平面图')}${icon('external')}</button><div class="visual-catalogue">${refs.map(ref=>`<button data-visual-ref="${esc(ref.featureId)}"><strong>${esc(ref.code||'•')} · ${esc(localized(data.places.find(p=>p.id===ref.featureId)?.name)||ref.nameEn)}</strong>${icon('external')}</button>`).join('')}</div>`);}


function placeDetail(){const p=data.places.find(p=>p.id===selected);if(!p)return;const description=localized(p.description).trim(),hasDescription=description!==''&&description!==localized(p.name).trim();dialog(`<span class="small-tag">${esc(p.code||'')}</span><h2>${esc(localized(p.name))}</h2>${hasDescription?`<p data-place-description>${esc(description)}</p>`:''}<p class="muted">${mapUsageNote()}</p>${naverButton(p.id)}<p class="muted">${L('Naver Maps opens externally and needs internet. A directory marker does not verify an entrance.','네이버 지도는 외부에서 열리며 인터넷이 필요합니다. 안내 지도의 표시는 출입구를 확인한 위치가 아닙니다.','Naver地图将在外部打开并需要联网。校园目录标记并不代表已核实的入口。')}</p>${p.evidence.sourceUrl?`<button class="primary-button" data-url="${esc(p.evidence.sourceUrl)}">${L('Building source','건물 출처')}${icon('external')}</button>`:''}<button class="source-link" data-action="map-evidence">${L('Map sources','지도 출처','地图来源')}</button>`);}
let toastTimer:number|undefined;function toast(text:string){$('toast').textContent=text;$('toast').hidden=false;clearTimeout(toastTimer);toastTimer=window.setTimeout(()=>{$('toast').hidden=true;},4000);}
document.addEventListener('click',e=>{const b=(e.target as HTMLElement).closest<HTMLButtonElement>('button');if(!b)return;
 // WebKit does not focus pointer-clicked buttons; remember an external dialog opener explicitly.
 if(!$('dialog').contains(b)&&(b.dataset.source||b.dataset.visualRef||['sources','about','map-evidence','place-detail','location-evidence'].includes(b.dataset.action||'')))b.focus({preventScroll:true});
 if(b.dataset.campusMap&&isCampusId(b.dataset.campusMap)){changeCampus(b.dataset.campusMap);return;}if(b.dataset.tab){if($<HTMLDialogElement>('dialog').open)closeDialog();setTab(b.dataset.tab as typeof tab);return;}if(b.dataset.place){if(b.dataset.chatMap!==undefined){if(isCampusId(b.dataset.placeCampus))openChatPlace(b.dataset.place,b.dataset.placeCampus,Number(b.dataset.chatMap));}else if(!b.dataset.placeCampus||b.dataset.placeCampus===campusId)selectPlace(b.dataset.place);return;}if(b.dataset.source){if($<HTMLDialogElement>('dialog').open)closeDialog();sourceDialog(b.dataset.source);return;}if(b.dataset.visualRef){if($<HTMLDialogElement>('dialog').open)closeDialog();showVisualReference(b.dataset.visualRef);return;}if(b.dataset.url){openExternal(b.dataset.url);return;}if(b.dataset.ask){ask(b.dataset.ask);return;}if(b.dataset.category){category=b.dataset.category;renderPanel();return;}if(b.dataset.foodKind){foodKind=b.dataset.foodKind;renderPanel();return;}
 const a=b.dataset.action;if(['sources','about','map-evidence','place-detail','location-evidence'].includes(a||'')&&$<HTMLDialogElement>('dialog').open)closeDialog();
 switch(a){case 'naver-map':openNaver();break;case 'return-chat':returnToChat();break;case 'community-refresh':requestCommunityRefresh();break;case 'my-location':startLocation();break;case 'location-center':if(scene?.recenterLocation())$('workspace').scrollTop=0;break;case 'location-stop':stopLocation();break;case 'location-evidence':locationEvidence();break;case 'retry-map':mount();break;case 'view':twoD=!twoD;scene?.set2D(twoD);$('view-toggle').textContent=twoD?'3D':'2D';break;case 'labels':labelsVisible=!labelsVisible;scene?.setLabelsVisible(labelsVisible);b.classList.toggle('active',labelsVisible);b.setAttribute('aria-pressed',String(labelsVisible));toast(labelsVisible?L('Building labels shown.','건물 이름표를 표시합니다.'):L('Labels hidden. The selected building stays labelled.','이름표를 숨깁니다. 선택한 건물은 계속 표시됩니다.'));break;case 'focus-search':focusBuildingSearch();break;case 'zoom-in':scene?.zoomBy(1.25);break;case 'zoom-out':scene?.zoomBy(.8);break;case 'rotate':scene?.rotate();break;case 'reset':scene?.reset();break;case 'favorite':if(selected){favorites.has(selected)?favorites.delete(selected):favorites.add(selected);persist();renderSheet();renderPlaces();}break;case 'saved-filter':onlySaved=!onlySaved;renderPanel();break;case 'close-place':if(chatMapReturn){returnToChat();break;}selected=null;scene?.select(null);renderSheet();renderPlaces();break;case 'place-detail':placeDetail();break;case 'map-evidence':mapEvidence();break;case 'sources':showSources();break;case 'about':about();break;case 'close-dialog':closeDialog();break;case 'clear-chat':messages=[];campusChats[campusId]=messages;renderMessages();toast(L('Chat cleared.','대화를 지웠습니다.'));break;case 'clear-saved':favorites.clear();persist();renderSheet();if(tab==='explore')renderPlaces();toast(L('Saved places cleared.','즐겨찾기를 지웠습니다.'));break;}
});
document.addEventListener('visibilitychange',()=>{if(document.hidden)pauseLocation();else resumePermissionLocation();syncSceneActivity();scheduleBusRefresh(true);});window.addEventListener('pagehide',()=>{stopLocation('paused');clearTimeout(busRefreshTimer);busRefreshTimer=undefined;});window.addEventListener('pageshow',()=>scheduleBusRefresh(true));window.addEventListener('offline',()=>toast(L('Offline. Saved campus information still works.','오프라인입니다. 저장된 캠퍼스 정보를 계속 이용할 수 있습니다.')));
window.MCE={receive:(m:any)=>{if(!m||typeof m!=='object')return;
 if(m.type==='community-state'){receiveCommunityState(m);return;}
 if(m.type==='preferences'){if(m.language==='en'||m.language==='ko'||m.language==='zh')lang=m.language;if(isCampusId(m.campusId)&&m.campusId!==campusId){chatMapReturn=null;campusSelections[campusId]=selected;campusId=m.campusId;data=datasets[campusId];selected=campusSelections[campusId];messages=campusChats[campusId];query='';category='all';foodKind='all';routeId=knowledge().busRoutes[0]?.id||'';}for(const chat of messages)chat.result=answerQuestion(chat.question,lang,campusId);onlySaved=false;if(Array.isArray(m.favorites))favorites=new Set(m.favorites.filter((v:unknown)=>typeof v==='string'));mount();}
 if(m.type==='publisher-info'){publisherPrivacy=typeof m.privacyUrl==='string'&&safeExternalUrl(m.privacyUrl)?m.privacyUrl:null;publisherSupport=typeof m.supportUrl==='string'&&safeExternalUrl(m.supportUrl)?m.supportUrl:null;}
 if(m.type==='lifecycle'){nativeActive=!!m.active;refreshCommunitySummaries();scheduleCommunityRefresh();if(!nativeActive)pauseLocation();else resumePermissionLocation();syncSceneActivity();scheduleBusRefresh(true);}
 if(m.type==='location-permission'){locationPermissionPending=!!m.pending;if(m.pending)permissionGrantedContinuation=false;else if(m.cancelled){if(locationIntent||currentFix||locationPhase==='active'||locationPhase==='requesting')stopLocation('paused');}else if(!m.granted)stopLocation('denied');else {permissionGrantedContinuation=resumeAfterPermission&&locationIntent;resumePermissionLocation();}renderLocation();}
 if(m.type==='font-scale'&&Number.isFinite(m.scale)){const scale=Math.max(1,Math.min(2,m.scale));document.documentElement.style.setProperty('--font-scale',String(scale));document.documentElement.dataset.largeText=String(scale>1.35);syncMapOcclusions();}
 if(m.type==='reduced-motion'){reducedMotion=!!m.enabled;scene?.setReducedMotion(reducedMotion);}if(m.type==='notice'&&typeof m.text==='string')toast(m.text);if(m.type==='select'&&typeof m.placeId==='string')selectPlace(m.placeId);
 if(m.type==='content'&&validateDataset(m.data,'live').length===0){const incoming=m.data as Dataset,id=contentCampusId(incoming);if(!id||incoming.version<datasets[id].version)return;const refs=CAMPUSES[id].referencePlaces();datasets[id]={...incoming,places:[...incoming.places,...refs.filter(p=>!incoming.places.some(q=>q.id===p.id))]};if(id!==campusId)return;data=datasets[id];contentState=m.cached?'cached':'updated';if(selected&&!data.places.some(p=>p.id===selected))selected=null;scene?.setData(data);scene?.setReferenceCampus(true);scene?.select(selected);renderPanel();renderSheet();}
},handleBack,diagnostics:()=>({...scene?.diagnostics(),mapMode}),getState:()=>({mode:'live',campusId,tab,selected,twoD,labelsVisible,favorites:[...favorites],language:lang,sceneFailed,route:null,locationStored:false,mapMode,locationPhase,locationVisible:fixOnMap,contentState,communityStatus,communityVersion:communitySnapshot?.version||0,chatMessages:messages.length})};
document.addEventListener('visibilitychange',()=>{refreshCommunitySummaries();scheduleCommunityRefresh();});
load();mount();scheduleCommunityRefresh();send({type:'ready'});



